        int u = state / C;
        int c = state % C;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int nc = c + edges[e].p;
            if (nc > V) continue;

            int ns = v * C + nc;
            int nd = d + edges[e].t;
            if (nd < dist[ns]) {
                dist[ns] = nd;
                heap_push(nd, ns);
